/* From Uiverse.io by adamgiebl - Tags: input */
.__UIV_SCOPE__ .input-wrapper input {
  background-color: #eee;
  border: none;
  padding: 1rem;
  font-size: 1rem;
  width: 13em;
  border-radius: 1rem;
  color: lightcoral;
  box-shadow: 0 0.4rem #dfd9d9;
  cursor: pointer;
}

.__UIV_SCOPE__ .input-wrapper input:focus {
  outline-color: lightcoral;
}
